const vec2 center = vec2(0., 0.);
const float x_span = 20.;

vec2 A = vec2(4., 3.5), B = vec2(-1.5, 4.), C = vec2(-3., -4.5);
vec3 weights = vec3(1., 2., 1.);

float point_r2 = .01;
float line_r = .03;

float dist2(vec2 a, vec2 b) {
    float dx = a.x-b.x, dy = a.y-b.y;
    return dx*dx + dy*dy;
}

bool in_line(vec2 pos, vec2 a, vec2 b) {
    float dx = b.x-a.x, dy = b.y-a.y;

    if (abs(dx) < abs(dy))
        return abs(pos.x - a.x - dx*(pos.y-a.y)/dy) < line_r;
    return abs(pos.y - a.y - dy*(pos.x-a.x)/dx) < line_r;
}

bool hit_point(vec2 pos) {
    if (dist2(pos, A) < point_r2) return true;
    if (dist2(pos, B) < point_r2) return true;
    if (dist2(pos, C) < point_r2) return true;
    return false;
}

bool hit_line(vec2 pos) {
    if (in_line(pos, A, B)) return true;
    if (in_line(pos, A, C)) return true;
    if (in_line(pos, B, C)) return true;
    return false;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // move points around to test things
    A.y = 2.*cos(iTime*1.3) + 2.;
    B.y = cos(iTime*1.7) + 3.;
    C.x = 2.*cos(iTime) - 1.;

    // get coord pos
    vec2 coord = (fragCoord / iResolution.x - vec2(.5, .5*iResolution.y/iResolution.x)) * x_span - center;

    if (hit_point(coord)) fragColor = vec4(1.);
    else if (hit_line(coord)) fragColor = vec4(.3);

    else {
        float dA = distance(coord, A);
        float dB = distance(coord, B);
        float dC = distance(coord, C);
        float average_dist = (dA+dB+dC)/3.;
        float r = 1. - abs(weights.x - average_dist/dA);
        float g = 1. - abs(weights.y - average_dist/dB);
        float b = 1. - abs(weights.z - average_dist/dC);

        fragColor = vec4(r*r, g*g, b*b, 1.);
    }
}
